    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle fire kritiske elementer er med: individuel samlet vurdering på lægefagligt grundlag, hvad den studerende fejler og påvirkningen af daglig funktion, behandling/effekt/restsymptomer/bivirkninger/rimelig medvirken samt varighed, gentagne perioder og tilbagefaldsrisiko. Det understøttende element om diagnose er ikke påkrævet."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvad Udbetaling Danmark lægger vægt på ved vurderingen af sværhedsgraden, uden irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som lovbestemmelse, vejledningsafsnit eller lignende. Det henviser kun generelt til Udbetaling Danmarks vurdering."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så gyldighed og aktualitet kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Ingen kilde er angivet, så det kan ikke vurderes, om passager understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Indholdet svarer til vejledningens afsnit 3.4.1.2 i det udleverede materiale. Svaret tilføjer ingen væsentlig regel, betingelse, undtagelse eller myndighed uden støtte."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bruger \"blandt andet\" og præsenterer dermed momenterne som illustrative. Det bevarer \"i rimeligt omfang\" for medvirken og \"risiko for tilbagefald\". Det fremstiller ikke momenterne som kumulative betingelser. Det fremgår, at der er tale om en individuel, samlet vurdering."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er enkelt og internt sammenhængende: først den overordnede ramme (individuel samlet vurdering, dokumentation), derefter momenterne. Konklusionen følger af disse trin."
    },
    "c10_legal_modality_precision": {
      "label": "met",
      "reason": "\"Skal være velbeskrevet og lægefagligt dokumenteret\" svarer til kilden. \"Lægges der blandt andet vægt på\" gengiver det illustrative \"f.eks.\" og gør ikke skønnet eller momenterne absolutte."
    }
  },
  "xhaile_coverage": {
    "A14": {
      "label": "yes",
      "reason": "Svaret siger udtrykkeligt, at funktionsnedsættelsen skal være velbeskrevet og lægefagligt dokumenteret, og gengiver de fire momentgrupper fra gold-teksten. Eksemplerne (migræne, tarmsygdom) og pointen om, at restsymptomer kan opfylde sværhedskriteriet selv ved behandlingseffekt, er ikke med, men de er ikke nødvendige for punktet."
    }
  },
  "overall_notes": "Indholdsmæssigt korrekt og komplet svar, der følger vejledningen tæt. Det angiver dog ingen kilde, så C04 er not_met, og C05 og C06 er not_assessable efter kildereglen."
}

